import{_ as i,o,c as a,a5 as s,j as t}from"./chunks/framework.B6tQOu6W.js";const n="/assets/dokploy.5LGQpvkx.png",l="/assets/dokploy-ui.Calj7RjW.png",r="/assets/dokploy-login.AW4fdOSY.png",p="/assets/dokploy-options.Dy4LgzA8.png",u="/assets/dokploy-create-project.7VlgoylE.png",d="/assets/dokploy-create-service.or8LBpX7.png",c="/assets/dokploy-create-service2.Cj1FgEcV.png",m="/assets/dokploy-deploy-step.BBZe7GJj.png",h="/assets/dokploy-server-ip.BhuCHQCN.png",v="/assets/ssh-key.DBNOIowf.png",k="/assets/deploy-vite.n1TABXLG.png",y="/assets/deploy-laravel.Blm_PxFo.png",b="/assets/database.Dzu4Gwc6.png",g="/assets/database-url-interne.CyE-6xLL.png",f="/assets/external_port.CbINf990.png",S=JSON.parse(`{"title":"Dokploy, le déploiement simplifié","description":"Dokploy, le déploiement simplifié et automatique d'applications et de sites web.","frontmatter":{"description":"Dokploy, le déploiement simplifié et automatique d'applications et de sites web."},"headers":[],"relativePath":"tp/devops/paas/dokploy.md","filePath":"tp/devops/paas/dokploy.md","lastUpdated":1769016074000}`),D={name:"tp/devops/paas/dokploy.md"};function q(E,e,P,C,x,z){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="dokploy-le-deploiement-simplifie" tabindex="-1">Dokploy, le déploiement simplifié <a class="header-anchor" href="#dokploy-le-deploiement-simplifie" aria-label="Permalink to &quot;Dokploy, le déploiement simplifié&quot;">​</a></h1><p>Nous l&#39;avons vu en cours. La force de Docker est la portabilité des conteneurs. Il est facile de déployer une configuration sur un serveur distant, avec un simple <code>docker compose up</code>. Mais est-il possible d&#39;automatiser ce déploiement ? La réponse est oui, et c&#39;est ce que nous allons voir dans ce TP.</p><details class="details custom-block"><summary>Sommaire</summary><nav class="table-of-contents"><ul><li><a href="#prerequis">Prérequis</a></li><li><a href="#les-solutions-existantes">Les solutions existantes</a></li><li><a href="#introduction-a-dokploy">Introduction à Dokploy</a><ul><li><a href="#pourquoi-choisir-dokploy">Pourquoi choisir Dokploy ?</a></li><li><a href="#fonctionnalites">Fonctionnalités</a></li></ul></li><li><a href="#installation">Installation</a></li><li><a href="#utilisation">Utilisation</a></li><li><a href="#et-voila">Et voilà !</a></li><li><a href="#quoi-deployer">Quoi déployer ?</a></li><li><a href="#comment-deployer">Comment déployer ?</a></li><li><a href="#creer-votre-premier-deploiement">Créer votre premier déploiement</a><ul><li><a href="#creer-un-deploiement">Créer un déploiement</a></li><li><a href="#comment-acceder-a-votre-service">Comment accéder à votre service ?</a></li><li><a href="#conclusion-de-ce-premier-deploiement">Conclusion de ce premier déploiement</a></li></ul></li><li><a href="#aller-plus-loin">Aller plus loin</a><ul><li><a href="#creer-une-clef-ssh">Créer une clef SSH</a></li></ul></li><li><a href="#deployer-un-site-avec-vitejs">Déployer un site avec ViteJS</a><ul><li><a href="#connectez-votre-repository-et-c-est-parti">Connectez votre repository et c&#39;est parti !</a></li></ul></li><li><a href="#deployer-un-site-laravel">Déployer un site Laravel</a></li><li><a href="#une-base-de-donnees-phpmyadmin">Une base de données + PHPMyAdmin</a><ul><li><a href="#ajouter-une-base-de-donnees">Ajouter une base de données</a></li><li><a href="#ajouter-phpmyadmin">Ajouter PHPMyAdmin</a></li><li><a href="#point-cyber">Point cyber</a></li></ul></li><li><a href="#configurer-l-auto-deploiement">Configurer l&#39;auto-deploiement</a></li><li><a href="#tester-c-est-bien">Tester c&#39;est bien !</a></li><li><a href="#conclusion">Conclusion</a></li></ul></nav></details><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><p>Pour ce TP, vous allez avoir besoin d&#39;une VM (avec ou sans docker). Si ce n&#39;est pas le cas, je vous invite à consulter l&#39;aide-mémoire <a href="/tp/devops/serveur/tp1.html">Installer Debian 13</a> (<a href="/tp/devops/serveur/tp1alt.html">ou via un modèle</a>).</p><div class="tip custom-block"><p class="custom-block-title">Votre serveur doit être vierge</p><p>Pour ce TP, votre serveur doit être vierge, c&#39;est-à-dire qu&#39;il ne doit pas avoir de service déjà installé (Apache, Nginx, etc.). Si ce n&#39;est pas le cas, je vous invite à réinitialiser votre VM.</p></div><h2 id="les-solutions-existantes" tabindex="-1">Les solutions existantes <a class="header-anchor" href="#les-solutions-existantes" aria-label="Permalink to &quot;Les solutions existantes&quot;">​</a></h2><p>Dans le monde du DevOps, il existe de nombreuses solutions pour automatiser le déploiement d&#39;applications. Évidemment, il existe de nombreuses solutions propriétaires (Vercel, Netlify, Heroku, etc.). Ces solutions sont très efficaces, mais elles peuvent avoir un coût non négligeable, et surtout elles sont hébergées chez un tiers. Parfois, il est nécessaire de déployer une solution sur son propre serveur, c&#39;est ici que les solutions open-source prennent tout leur sens.</p><p>Dans le monde de l&#39;open-source, idem, il existe beaucoup de possibilités, les plus connues étant :</p><ul><li>CapRover.</li><li>Dokku.</li><li>Coolify.</li></ul><p>En fonction de vos besoins, vous pourrez choisir l&#39;une ou l&#39;autre de ces solutions. Pour ce TP, nous allons nous concentrer sur <a href="https://dokploy.com" target="_blank" rel="noreferrer">Dokploy</a>.</p><div class="tip custom-block"><p class="custom-block-title">Besoin de comparer ?</p><p>Dokploy propose sur son site une <a href="https://docs.dokploy.com/docs/core/comparison" target="_blank" rel="noreferrer">comparaison</a> avec les autres solutions du marché.</p><p>Avant de vous lancer, je vous invite à regarder cette page pour partir avec une bonne idée des avantages et inconvénients de chaque solution.</p></div><h2 id="introduction-a-dokploy" tabindex="-1">Introduction à Dokploy <a class="header-anchor" href="#introduction-a-dokploy" aria-label="Permalink to &quot;Introduction à Dokploy&quot;">​</a></h2><p><a href="https://dokploy.com" target="_blank" rel="noreferrer">Dokploy</a> est une solution de déploiement stable et facile à utiliser, conçue pour simplifier la gestion des applications. Pensez à Dokploy comme une alternative gratuite et auto-hébergeable à des plateformes comme Heroku, Vercel et <a href="/tp/ci/jamstack/netlify.html">Netlify</a>, en tirant parti de la robustesse de <a href="/cours/docker.html">Docker</a> et de la flexibilité de <a href="https://traefik.io/" target="_blank" rel="noreferrer">Traefik</a>.</p><p><img src="'+n+'" alt="Dokploy" loading="lazy"></p><h3 id="pourquoi-choisir-dokploy" tabindex="-1">Pourquoi choisir Dokploy ? <a class="header-anchor" href="#pourquoi-choisir-dokploy" aria-label="Permalink to &quot;Pourquoi choisir Dokploy ?&quot;">​</a></h3><ul><li>Simplicité : Configuration et gestion des déploiements faciles.</li><li>Flexibilité : Prend en charge un large éventail d&#39;applications et de bases de données.</li><li>Open Source : Logiciel libre et open source, accessible à tous.</li></ul><h3 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><ul><li><strong>Déploiement simple</strong> : Déployez vos applications via une interface graphique en quelques minutes.</li><li><strong>Gestion des domaines</strong> : Gérez facilement vos domaines et sous-domaines.</li><li><strong>Gestion des bases de données</strong> : Prend en charge un large éventail de bases de données (sans configuration).</li><li><strong>Gestion des variables d&#39;environnement</strong> : Gérez vos variables d&#39;environnement en toute simplicité (configuration dynamique).</li></ul><p><img src="'+l+'" alt="Dokploy" loading="lazy"></p><p>Évidemment, ici, nous allons nous concentrer sur la partie installation et déploiement. Mais, une fois installé, je vous invite à explorer les différentes fonctionnalités de Dokploy. Vous allez certainement trouver des fonctionnalités qui vous seront utiles.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>L&#39;installation de Dokploy dans un serveur est très simple, dans la documentation officielle, vous trouverez la commande suivante :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://dokploy.com/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="danger custom-block"><p class="custom-block-title">Attention</p><p>Cette commande est pratique, mais attention, en cybersécurité, il est déconseillé de lancer un script directement depuis internet. Il est préférable de télécharger le script, de le lire, et de le lancer ensuite.</p></div><p>Si vous téléchargez le script, vous verrez qu&#39;il est très simple. Voici ce qu&#39;il réalise :</p><ul><li>Vérifie si le script est exécuté en tant que root.</li><li>Vérifie si le système d&#39;exploitation est Linux.</li><li>Vérifie si le script est exécuté à l&#39;intérieur d&#39;un conteneur Docker.</li><li>Vérifie si les ports 80 et 443 sont libres.</li><li>Installe Docker si ce n&#39;est pas déjà fait.</li><li>Initialise un Docker Swarm</li><li>Crée un réseau Docker overlay nommé <code>dokploy-network</code>.</li><li>Télécharge l&#39;image Docker de Dokploy.</li><li>Crée un service Docker pour Dokploy avec les paramètres nécessaires.</li><li>Affiche un message de succès avec l&#39;adresse pour accéder à l&#39;interface de Dokploy.</li></ul><div class="tip custom-block"><p class="custom-block-title">Docker Swarm ?</p><p>Docker Swarm est un outil de clustering et d&#39;orchestration de conteneurs Docker. Il permet de gérer un cluster de nœuds Docker en tant que ressource unique. Dans notre cas, cette partie est complètement transparente, Dokploy s&#39;occupe de tout.</p></div><h2 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h2><p>Une fois Dokploy installé, vous pouvez accéder à l&#39;interface Web de celui-ci en vous rendant sur l&#39;adresse IP de votre serveur sur le port 3000. Lors de la première connexion, vous devrez créer un compte administrateur.</p><p><img src="'+r+'" alt="Dokploy" loading="lazy"></p><p>D&#39;un point de vue cyber, le choix de votre mot de passe est très important. En effet, Dokploy va permettre la création, le déploiement et la gestion de vos applications. Il est donc important de choisir un mot de passe fort.</p><p>Une fois connecté, vous arrivez sur l&#39;interface de Dokploy. Vous pouvez maintenant commencer à déployer vos applications.</p><h2 id="et-voila" tabindex="-1">Et voilà ! <a class="header-anchor" href="#et-voila" aria-label="Permalink to &quot;Et voilà !&quot;">​</a></h2><p>C&#39;est tout… Et oui, à ce stade, vous avez tout ce qu&#39;il vous faut pour déployer vos applications via Dokploy, nous allons maintenant nous intéresser à la partie <strong>quoi déployer</strong>.</p><h2 id="quoi-deployer" tabindex="-1">Quoi déployer ? <a class="header-anchor" href="#quoi-deployer" aria-label="Permalink to &quot;Quoi déployer ?&quot;">​</a></h2><p>Vous avez plusieurs solutions, l&#39;outil que vous avez installé est très flexible, il est possible de déployer des applications de plusieurs types :</p><ul><li>Via Docker seulement (un simple <code>Dockerfile</code> est suffisant).</li><li>Via Docker Compose (pour des applications plus complexes).</li><li>Un site statique (HTML, CSS, JS), sans Docker, juste en déposant les fichiers.</li></ul><h2 id="comment-deployer" tabindex="-1">Comment déployer ? <a class="header-anchor" href="#comment-deployer" aria-label="Permalink to &quot;Comment déployer ?&quot;">​</a></h2><p>Ici aussi, plusieurs possibilités :</p><ul><li>Via Github.</li><li>Via Gitlab.</li><li>Via Bitbucket.</li><li>Via un repository Git privé (en utilisant l&#39;URL du repository).</li><li>Via Docker Hub (pour des images Docker).</li><li>Via un fichier ZIP (pour un site déployé très rapidement).</li></ul><p>Nous n&#39;allons bien évidemment pas tout tester. Mais sachez que la solution est très flexible. À vous de choisir la méthode qui vous convient le mieux.</p><p><img src="'+p+'" alt="Dokploy" loading="lazy"></p><h2 id="creer-votre-premier-deploiement" tabindex="-1">Créer votre premier déploiement <a class="header-anchor" href="#creer-votre-premier-deploiement" aria-label="Permalink to &quot;Créer votre premier déploiement&quot;">​</a></h2><p>Pour tester simplement Dokploy, je vous propose de déployer une image Docker existante sur Docker Hub. Pour cela, plusieurs choix, mais nous allons prendre une image très légère, le serveur web Nginx.</p><div class="tip custom-block"><p class="custom-block-title">Point terminologie.</p><p>Dokploy repose sur deux niveaux de catégorisation, le premier est le projet, c&#39;est le groupe de services qui vont être déployés ensemble. Le second est le service, c&#39;est l&#39;élément qui va être déployé (un conteneur Docker, un site statique, une base de données, etc.).</p></div><h3 id="creer-un-deploiement" tabindex="-1">Créer un déploiement <a class="header-anchor" href="#creer-un-deploiement" aria-label="Permalink to &quot;Créer un déploiement&quot;">​</a></h3><ol><li>Connectez-vous à l&#39;interface de Dokploy.</li><li>« + Create project »</li></ol><p><img src="'+u+'" alt="Création d&#39;un projet" loading="lazy"></p><ol start="3"><li>Nommez votre projet (par exemple <code>nginx</code>).</li><li>Créer un nouveau service de type « Application ».</li><li>Nommer votre service (par exemple <code>Frontend</code>).</li></ol><p><img src="'+d+'" alt="Création d&#39;un service" loading="lazy"><img src="'+c+'" alt="Choix du service" loading="lazy"></p><ol start="6"><li>Choisissez la méthode de déploiement (Docker Hub) et entrez le nom de l&#39;image (par exemple <code>nginx:latest</code>).</li><li>Cliquez sur « Deploy ».</li></ol><p><img src="'+m+'" alt="Étape du déploiement" loading="lazy"></p><p>Patientez quelques instants, et vous devriez voir votre service déployé. Vous pouvez suivre l&#39;avancement du déploiement dans l&#39;onglet « Deployments ».</p><h3 id="comment-acceder-a-votre-service" tabindex="-1">Comment accéder à votre service ? <a class="header-anchor" href="#comment-acceder-a-votre-service" aria-label="Permalink to &quot;Comment accéder à votre service ?&quot;">​</a></h3><p>Vous avez un nom de domaine ? Aucun problème, il suffit d&#39;ajouter un enregistrement DNS pour pointer vers votre serveur.</p><p>Pour tester, Dokploy intègre un système de nom de domaine « dynamique » (qui fonctionne seulement en interne). Pouvez l&#39;utiliser en allant dans l&#39;interface de Dokploy, configurer l&#39;onglet « Domains » pour ajouter un domaine en utilisant le petit symbole « aléatoire » (une sorte de dé).</p><div class="danger custom-block"><p class="custom-block-title">Attention</p><p>Pour que cela fonctionne vous devez vérifier que votre IP est bien configurée dans les paramètres de Dokploy :</p><p><img src="'+h+'" alt="IP" loading="lazy"></p></div><div class="tip custom-block"><p class="custom-block-title">Vous voulez un nom de domaine personnalisé ?</p><p>Le service traefik.me est plutôt intéressant. Il fonctionne sur le principe d&#39;un sous-domaine contenant l&#39;IP de destination. Exemple :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://bts-sio-127-0-0-1.traefik.me</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Dans cet exemple le domaine <code>bts-sio-127-0-0-1.traefik.me</code> pointe vers l&#39;IP <code>127.0.0.1</code>. C&#39;est très pratique pour avoir une configuration basée sur des noms de domaine sans avoir à exposer votre serveur sur internet.</p></div><p>Et voilà, vous avez déployé votre premier service via Dokploy. Simple, non ?</p><h3 id="conclusion-de-ce-premier-deploiement" tabindex="-1">Conclusion de ce premier déploiement <a class="header-anchor" href="#conclusion-de-ce-premier-deploiement" aria-label="Permalink to &quot;Conclusion de ce premier déploiement&quot;">​</a></h3><p>Vous avez maintenant déployé une image Docker déjà construite. Je pense que vous l&#39;avez compris… c&#39;est très simple. Je vous propose maintenant d&#39;aller plus loin, en déployant une application plus complexe, avec un <code>Dockerfile</code>.</p><h2 id="aller-plus-loin" tabindex="-1">Aller plus loin <a class="header-anchor" href="#aller-plus-loin" aria-label="Permalink to &quot;Aller plus loin&quot;">​</a></h2><p>Pour aller plus loin, nous allons maintenant déployer une application plus complexe que nous avons versionnée sur Github / Gitlab / autre. Pour cela, dans un premier temps, nous allons devoir autoriser Dokploy à accéder à notre repository.</p><h3 id="creer-une-clef-ssh" tabindex="-1">Créer une clef SSH <a class="header-anchor" href="#creer-une-clef-ssh" aria-label="Permalink to &quot;Créer une clef SSH&quot;">​</a></h3><p>Dans le menu, rendez-vous dans « SSH Keys » puis « + Add SSH Key ».</p><p><img src="'+v+`" alt="SSH Key" loading="lazy"></p><p>Une fois généré, vous pouvez ajouter cette clef SSH sur votre projet dans la partie « Settings » puis « Deploy Keys ». Ou bien, vous pouvez ajouter cette clef SSH sur votre compte Github / Gitlab.</p><div class="tip custom-block"><p class="custom-block-title">Important</p><p>Cette étape est importante, si vous ne le faites pas, Dokploy ne pourra pas accéder à votre repository. Et donc, vous ne pourrez pas déployer votre application.</p></div><h2 id="deployer-un-site-avec-vitejs" tabindex="-1">Déployer un site avec ViteJS <a class="header-anchor" href="#deployer-un-site-avec-vitejs" aria-label="Permalink to &quot;Déployer un site avec ViteJS&quot;">​</a></h2><p>Pour ce second exemple, nous allons déployer un site statique, mais un peu plus complexe. Nous allons utiliser ViteJS, un outil de développement pour les applications web modernes. Pour cela, nous allons créer un nouveau projet ViteJS :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vite@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-dokploy</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pour ce déploiement, nous allons utiliser <a href="https://nixpacks.com/" target="_blank" rel="noreferrer">nixpacks</a>, cet outil permet d&#39;éviter la création d&#39;un fichier <code>Dockerfile</code>. Dans votre projet, créer un fichier <code>nixpacks.toml</code> avec le contenu suivant :</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">phases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nixPkgs = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;nodejs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">phases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmds = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;npm i&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">phases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmds = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;npm run build&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">Nixpacks ?</p><p>Ce fichier contient l&#39;ensemble des commandes pour construire votre application. Ce fichier sera utilisé par Dokploy (via nixpacks) pour construire votre application puis la déployer.</p><p>Nous aurions pu utiliser un <code>Dockerfile</code>, mais nixpacks est une solution plus simple et plus rapide pour déployer des applications.</p></div><p>Puis, nous allons partager ce projet sur Github, Gitlab ou autre (en privé ou public, ça n&#39;a pas d&#39;importance).</p><h3 id="connectez-votre-repository-et-c-est-parti" tabindex="-1">Connectez votre repository et c&#39;est parti ! <a class="header-anchor" href="#connectez-votre-repository-et-c-est-parti" aria-label="Permalink to &quot;Connectez votre repository et c&#39;est parti !&quot;">​</a></h3><p>Je vous laisse reprendre les étapes précédentes pour créer un projet et un service. Cette fois-ci, vous allez choisir la méthode de déploiement « Git Repository » et entrer l&#39;URL de votre repository. Vous pouvez configurer le projet comme ceci :</p><p><img src="`+k+'" alt="Projet ViteJS" loading="lazy"></p><p>Cliquez sur « Deploy ». Si tout va bien, vous devriez voir dans les logs de déploiement :</p><p>Docker Deployed: ✅</p><p>À partir de là, vous pouvez configurer un domaine, et accéder à votre site.</p><h2 id="deployer-un-site-laravel" tabindex="-1">Déployer un site Laravel <a class="header-anchor" href="#deployer-un-site-laravel" aria-label="Permalink to &quot;Déployer un site Laravel&quot;">​</a></h2><p>Pour ce second exemple, nous allons déployer un site Laravel.</p><p>Deux solutions s&#39;offrent à nous :</p><ul><li>Créer un <code>Dockerfile</code> pour notre application. Je vous laisse suivre le TP <a href="/tp/ops/deployer-laravel-docker.html">Déployer un site Laravel avec Docker</a> qui vous explique les différentes étapes (c&#39;est très simple).</li><li>Laisser Nixpacks s&#39;occuper de la construction de notre application. (ça fonctionne très bien et normalement sans problème).</li></ul><p>Je vous laisse commiter votre projet sur Github, Gitlab ou autre, et vous pourrez ensuite le déployer via Dokploy.</p><p>Ici la démarche sera similaire à celle de ViteJS, vous allez choisir la méthode de déploiement « Git Repository » et entrer l&#39;URL de votre repository. Si vous avez choisi la version Dockerfile, alors la seule différence sera que vous allez devoir spécifier à Dokploy que nous allons déployer en mode Dockerfile :</p><p><img src="'+y+'" alt="Projet Laravel" loading="lazy"></p><p>Une fois le Git configuré, vous devez renseigner le contenu de votre <code>.env</code> dans l&#39;onglet « Environment » de Dokploy. Ce sont ces variables qui seront utilisées par votre application Laravel. Ici donc pas besoin de les mettre dans le fichier <code>.env</code> de votre projet (comme nous l&#39;avons vu en cours, ce fichier contient des informations sensibles <strong>et ne doit pas être versionné</strong>).</p><p>Cliquez sur « Deploy », patientez puis votre site Laravel sera déployé. Il ne vous restera plus qu&#39;à configurer un domaine pour accéder à votre site.</p><h2 id="une-base-de-donnees-phpmyadmin" tabindex="-1">Une base de données + PHPMyAdmin <a class="header-anchor" href="#une-base-de-donnees-phpmyadmin" aria-label="Permalink to &quot;Une base de données + PHPMyAdmin&quot;">​</a></h2><p>Il est également possible de déployer une base de données via Dokploy. L&#39;interface est très simple, vous pouvez choisir entre plusieurs types de bases de données (MySQL, PostgreSQL, etc.).</p><h3 id="ajouter-une-base-de-donnees" tabindex="-1">Ajouter une base de données <a class="header-anchor" href="#ajouter-une-base-de-donnees" aria-label="Permalink to &quot;Ajouter une base de données&quot;">​</a></h3><p>Vous avez besoin d&#39;une base de données ? Pas de problème, vous avez dans le menu « + Create service » la possibilité de créer un service de type « Database ». Vous pouvez choisir entre plusieurs types (et version) de base de données :</p><p><img src="'+b+'" alt="Base de données" loading="lazy"></p><p>Remplissez les informations nécessaires (nom, utilisateur, mot de passe, etc.) et cliquez sur « Deploy ». Vous pouvez ensuite lier ce service à votre application.</p><p>Votre base de données sera déployée de manière « interne », c&#39;est-à-dire que seuls les services de votre projet pourront y accéder. Le lien d&#39;accès à configurer dans votre projet est disponible dans le détail de la configuration :</p><p><img src="'+g+'" alt="Base de données" loading="lazy"></p><p>Ce nom sera le <code>nom de l&#39;hôte</code> de votre base de données (à définir par exemple dans le fichier <code>.env</code> de votre application Laravel).</p><div class="tip custom-block"><p class="custom-block-title">Vous souhaitez la rendre accessible depuis l&#39;extérieur ?</p><p>Si vous souhaitez vous connecter depuis le réseau local (ou depuis un autre serveur), vous pouvez également activer un « port » pour rendre votre base de données accessible depuis l&#39;exterieur.</p><p><img src="'+f+'" alt="Base de données" loading="lazy"></p></div><h3 id="ajouter-phpmyadmin" tabindex="-1">Ajouter PHPMyAdmin <a class="header-anchor" href="#ajouter-phpmyadmin" aria-label="Permalink to &quot;Ajouter PHPMyAdmin&quot;">​</a></h3><p>PhpMyAdmin n&#39;est pas le seul outil pour gérer une base de données. Même si je vous encourage à utiliser plutôt un client SQL (comme DBeaver), il est possible de déployer PhpMyAdmin via Dokploy. Voici un exemple vidéo de configuration :</p>',103),t("iframe",{width:"560",height:"315",src:"https://www.youtube-nocookie.com/embed/JL1dYJX1y4g?si=3gpD2XYXHCs0a8J3",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""},null,-1),s(`<p>Pour changer j&#39;ai utilisé le mode <code>Docker Compose</code> pour le déployer. Voici la configuration :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  phpmyadmin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">phpmyadmin/phpmyadmin:5.2.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      PMA_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">À-REMPLACER-PAR-LE-HOST-DE-VOTRE-BDD-INDIQUÉ-DANS-LA-CONFIGURATION-DE-VOTRE-BDD (voir vidéo)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      PMA_ARBITRARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">Une alternative ?</p><p>Vous pouvez également déployer PHPMyAdmin en mode <code>Application</code> en utilisant l&#39;image <code>phpmyadmin/phpmyadmin:5.2.1</code> et en configurant les variables d&#39;environnement <code>PMA_HOST</code> et <code>PMA_ARBITRARY</code> dans l&#39;onglet « Environment ».</p></div><h3 id="point-cyber" tabindex="-1">Point cyber <a class="header-anchor" href="#point-cyber" aria-label="Permalink to &quot;Point cyber&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Sécurité</p><p>Nous installons ici un outil qui permet de gérer la base de données. Il est important de sécuriser cet outil. Vous devez donc impérativement avoir un mot de passe fort pour l&#39;accès à votre base de données.</p><p>Autre point important, je vous conseille vivement de ne pas exposer le port <code>3306</code> de votre base de données sur Internet. Il est préférable de le garder uniquement ouvert au sein du réseau interne de Docker. Si réellement vous avez besoin d&#39;accéder à votre base de données depuis l&#39;exterieur (ex depuis C#), alors je vous conseille de choisir un port aléatoire différent du port <code>3306</code> et de le configurer dans votre application.</p></div><h2 id="configurer-l-auto-deploiement" tabindex="-1">Configurer l&#39;auto-deploiement <a class="header-anchor" href="#configurer-l-auto-deploiement" aria-label="Permalink to &quot;Configurer l&#39;auto-deploiement&quot;">​</a></h2><p>L&#39;auto-deploiement est une fonctionnalité très intéressante de Dokploy. Elle permet de déployer automatiquement votre application à chaque push sur votre repository. Pour cela, rendez-vous dans les paramètres de votre projet, puis dans l&#39;onglet « Deployment ».</p><p><a href="https://docs.dokploy.com/docs/core/auto-deploy" target="_blank" rel="noreferrer">Puis suivez les étapes décrite ici</a></p><p>L&#39;auto-déploiement repose sur un webhook, c&#39;est-à-dire une URL que vous allez devoir ajouter dans les paramètres de votre repository. À chaque push, votre repository enverra une requête à cette URL, et Dokploy déclenchera un déploiement.</p><p>Cela sous entend que votre serveur doit être accessible depuis votre serveur Gitlab / Github. Si vous utilisez <strong>le Gitlab de la section aucun problème.</strong></p><h2 id="tester-c-est-bien" tabindex="-1">Tester c&#39;est bien ! <a class="header-anchor" href="#tester-c-est-bien" aria-label="Permalink to &quot;Tester c&#39;est bien !&quot;">​</a></h2><p>Je vous laisse tester le déploiement en mode zip.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Dans ce TP nous avons exploré comment déployer différents types de site via une solution de PaaS (Plateform As A Service) open-source, Dokploy. Nous avons vu comment déployer une image Docker, un site statique, un site ViteJS et un site Laravel.</p><p>L&#39;idée ici n&#39;est pas de vous montrer toutes les possibilités de Dokploy, mais plutôt de vous montrer que c&#39;est très simple de déployer une application via une solution open-source.</p><p>Happy deployment !</p>`,16)])])}const A=i(D,[["render",q]]);export{S as __pageData,A as default};
